    return p.stdout.decode(), p.stderr.decode(), p.returncode

# syntax theme None etc truncated earlier
for args in [
 ["--no-gitconfig","--syntax-theme=Dracula","--show-config"],
 ["--no-gitconfig","--syntax-theme=None","--show-config"],
 ["--no-gitconfig","--minus-style=red","--show-config"],
]:
    o,e,c=run(args)
    print(args,c,e[:500])
    for l in o.splitlines():
        if "syntax-theme" in l or "minus-" in l or "plus-" in l or "blame" in l: print(repr(l))

# COLORTERM
for ct in [None,"truecolor","24bit",""]:
    env={} if ct is None else {"COLORTERM":ct}
    o,e,c=run(["--no-gitconfig","--show-config"], env)
    print("COLORTERM",ct, [l for l in o.splitlines() if "true-color" in l or "minus-style" in l])

# width env COLUMNS / terminal?
