env={"HOME":"/tmp/fakehome","PATH":"/usr/bin:/bin"}
def run(body):
    inp="diff --git a/f.txt b/f.txt\n--- a/f.txt\n+++ b/f.txt\n@@ -1,10 +1,10 @@\n"+body
    args=["./executable","--no-gitconfig","--paging=never","--syntax-theme=none","--width=80","--file-style=omit","--hunk-header-style=omit"]
    p=subprocess.run(args, input=inp.encode(), capture_output=True, env=env)
    o=p.stdout.decode()
    return "124" in o or "28m" in o  # emph bg present?
for n in range(1,11):
    for k in range(0,n+1):
        minus=" ".join(["a"]* (n-k) + ["b"]*k) if False else None
        # construct: tokens common first n-k, diff k
        mtoks=["w"+str(i) for i in range(n)]
        ptoks=mtoks.copy()
        for i in range(k): ptoks[-(i+1)]="x"+str(i)
        body="-"+" ".join(mtoks)+"\n+"+" ".join(ptoks)+"\n"
        print(f"n={n} k_diff_end={k} paired={run(body)}")
    print()
