import subprocess, os
env={"HOME":"/tmp/fakehome","PATH":"/usr/bin:/bin"}
def paired(a,b,maxd):
    body=f"-{a}\n+{b}\n"
    inp="diff --git a/f.txt b/f.txt\n--- a/f.txt\n+++ b/f.txt\n@@ -1,10 +1,10 @@\n"+body
    args=["./executable","--no-gitconfig","--paging=never","--syntax-theme=none","--width=80","--file-style=omit","--hunk-header-style=omit", f"--max-line-distance={maxd}"]
    p=subprocess.run(args, input=inp.encode(), capture_output=True, env=env)
    return "48;5;124" in p.stdout.decode()
def thresh(a,b):
    vals=[i/100 for i in range(0,101)]
    ps=[paired(a,b,v) for v in vals]
    # find first true
    for v,p in zip(vals,ps):
        if p: return v, ps
    return None, ps
pairs=[("aa bb cc","aa xx yy"),("hello world foo","hello xxx yyy"),("one two three","one xxx yyy"),("a b c","a y z"),("hello world","hello brave world"),("abcd","abxy"),("foo bar baz","foo qux baz")]
for a,b in pairs:
    t,ps=thresh(a,b); print(a,b,"first_true_at_0.01",t)
