            st.attrs.add(ATTR_CANON[low]); continue
        if low=='raw':
            st.is_raw=True; continue
        if low=='omit':
            st.is_omit=True; continue
        if low=='file':
            st.is_file=True; continue
        if low=='line-number':
            st.is_line_number=True; continue
