                col=res
            elif isinstance(res, Style):
                # whole-token style reference as a color slot: adopt its fg/bg/attrs?
                # For cases like token = another style name, merge
                if res.fg is not None:
                    if color_count==0: st.fg=res.fg; color_count+=1
                    elif color_count==1: st.bg=res.fg; color_count+=1
                    else: raise StyleError(f"Invalid style string: {s}. See the STYLES section of delta --help.")
