            col=parse_color_token(tok)
        if col is None:
            raise StyleError(f"Invalid color or style attribute: {tok}")
        if col.kind=='raw_special':
            st.is_raw=True; continue
        if color_count==0:
            st.fg=col; st.explicit_fg=True; color_count+=1
        elif color_count==1:
            if col.kind=='syntax':
