        if st.decoration is None:
            if 'ul' in st.attrs:
                st.decoration='ul'
        elif st.decoration=='ol' and 'ul' in st.attrs:
            st.decoration='ul ol'
        # if style string is exactly "none", decoration none already
        # empty string => decoration None (no decoration)
        if s.strip()=='':
            st.decoration=None
    return st

