OPT_BY_NAME={o[0]:o for o in OPTS}
OPT_BY_SHORT={o[1]:o for o in OPTS if o[1]}
def opt_display(name):
    o=OPT_BY_NAME[name]
    if o[3]=='flag': return f"--{name}"
    return f"--{name} <{o[2]}>"
def bin_name():
    return os.path.basename(sys.argv[0]) or 'delta'
def clap_usage_long():
    parts=[]
    for o in OPTS:
        parts.append(opt_display(o[0]))
    return f"\x1b[1m\x1b[4mUsage:\x1b[0m \x1b[1m{bin_name()}\x1b[0m <"+"|".join(parts)+"|MINUS_FILE|PLUS_FILE>"
def clap_usage_short():
    return f"\x1b[1m\x1b[4mUsage:\x1b[0m \x1b[1m{bin_name()}\x1b[0m [OPTIONS] [MINUS_FILE] [PLUS_FILE]"
def clap_error(msg, usage=None, tip=None):
    out=f"\x1b[1m\x1b[31merror:\x1b[0m {msg}\n"
    if tip:
        out+=f"\n  \x1b[32mtip:\x1b[0m {tip}\n"
    out+=f"\n{usage or clap_usage_short()}\n\nFor more information, try '\x1b[1m--help\x1b[0m'.\n"
    sys.stderr.write(out)
    raise SystemExit(2)

def _levenshtein(a,b):
    if a==b: return 0
    la,lb=len(a),len(b)
    prev=list(range(lb+1))
    for i in range(1,la+1):
        cur=[i]+[0]*lb
        for j in range(1,lb+1):
            cur[j]=min(prev[j]+1, cur[j-1]+1, prev[j-1]+(0 if a[i-1]==b[j-1] else 1))
        prev=cur
    return prev[lb]
def _similar(name, candidates):
    # approximate clap suggestion (Jaro-Winkler-ish): use prefix / edit distance heuristics
    best=None; bestscore=-1
    for cand in candidates:
        # jaro-winkler
        s1,s2=name,cand
        if s1==s2: score=1.0
        else:
            # jaro
            if not s1 or not s2: score=0.0
            else:
                md=max(len(s1),len(s2))//2-1
                if md<0: md=0
                m=0; s2_used=[False]*len(s2); s1_match=[False]*len(s1)
                for i,ch in enumerate(s1):
                    lo=max(0,i-md); hi=min(len(s2), i+md+1)
                    for j in range(lo,hi):
                        if not s2_used[j] and s2[j]==ch:
                            s1_match[i]=True; s2_used[j]=True; m+=1; break
                if m==0: score=0.0
                else:
                    t=0; k=0
                    for i in range(len(s1)):
                        if s1_match[i]:
                            while not s2_used[k]: k+=1
                            if s1[i]!=s2[k]: t+=1
                            k+=1
                    t//=2
                    score=(m/len(s1)+m/len(s2)+(m-t)/m)/3
                    # winkler prefix bonus
                    p=0
                    for i in range(min(4,min(len(s1),len(s2)))):
                        if s1[i]==s2[i]: p+=1
                        else: break
                    score+=p*0.1*(1-score)
        if score>bestscore:
            bestscore=score; best=cand
    if best is not None and bestscore>0.8:
        return best
    return None

class CliResult:
    def __init__(self):
        self.values={}; self.explicit=set(); self.positionals=[]

def parse_cli(argv):
    res=CliResult()
    i=0; seen=set(); end_opts=False
    def value_error(name, val, reason):
        clap_error(f"invalid value '\x1b[33m{val}\x1b[0m' for '\x1b[1m{opt_display(name)}\x1b[0m': {reason}")
    def validate(name, val):
        o=OPT_BY_NAME[name]
        if o[3]=='uint':
            if not re.fullmatch(r'\d+', val or ''):
                # distinguish too large
                if val and re.fullmatch(r'\d+', val):
                    pass
                value_error(name,val,"invalid digit found in string")
            try:
                v=int(val)
                if v>2**64-1: value_error(name,val,"number too large to fit in target type")
            except SystemExit: raise
            except Exception: value_error(name,val,"invalid digit found in string")
            return v
        if o[3]=='float':
            try: return float(val)
            except Exception: value_error(name,val,"invalid float literal")
        if o[3]=='enum':
            if val not in o[4]:
                poss=", ".join(f"\x1b[32m{x}\x1b[0m" for x in o[4])
                msg=f"invalid value '\x1b[33m{val}\x1b[0m' for '\x1b[1m{opt_display(name)}\x1b[0m'\n  [possible values: {poss}]"
                sim=_similar(val, o[4])
                tip=None
                extra=""
                if sim: extra=f"\n\n  \x1b[32mtip:\x1b[0m a similar value exists: '\x1b[32m{sim}\x1b[0m'"
                sys.stderr.write(f"\x1b[1m\x1b[31merror:\x1b[0m {msg}{extra}\n\nFor more information, try '\x1b[1m--help\x1b[0m'.\n"); raise SystemExit(2)
            return val
        return val
    while i < len(argv):
        arg=argv[i]
        if end_opts:
            res.positionals.append(arg); 
            if len(res.positionals)>2: clap_error(f"unexpected argument '\x1b[33m{arg}\x1b[0m' found")
            i+=1; continue
        if arg=='--':
            end_opts=True; i+=1; continue
        if arg=='--help':
            sys.stdout.write(data_text('help_long.txt')); raise SystemExit(0)
        if arg=='--version':
            sys.stdout.write(VERSION+"\n"); raise SystemExit(0)
        if arg.startswith('--'):
            body=arg[2:]
            if '=' in body: name,val=body.split('=',1); has_val=True
            else: name,val=body,None; has_val=False
            if name=='help':
                sys.stdout.write(data_text('help_long.txt')); raise SystemExit(0)
            if name=='version':
                sys.stdout.write(VERSION+"\n"); raise SystemExit(0)
            if name not in OPT_BY_NAME:
                sim=_similar(name, [o[0] for o in OPTS]+['help','version'])
                if sim:
                    sug='--'+sim
                    clap_error(f"unexpected argument '\x1b[33m--{name}\x1b[0m' found", usage=clap_usage_long(), tip=f"a similar argument exists: '\x1b[32m{sug}\x1b[0m'")
                else:
                    clap_error(f"unexpected argument '\x1b[33m--{name}\x1b[0m' found", tip=f"to pass '\x1b[33m--{name}\x1b[0m' as a value, use '\x1b[32m-- --{name}\x1b[0m'")
            o=OPT_BY_NAME[name]
            if name in seen:
                clap_error(f"the argument '\x1b[33m{opt_display(name)}\x1b[0m' cannot be used multiple times")
            seen.add(name)
            if o[3]=='flag':
                if has_val:
                    # usage special: executable --dark [MINUS...]
                    usage=f"\x1b[1m\x1b[4mUsage:\x1b[0m \x1b[1m{bin_name()}\x1b[0m \x1b[1m--{name}\x1b[0m [MINUS_FILE] [PLUS_FILE]"
                    clap_error(f"unexpected value '\x1b[33m{val}\x1b[0m' for '\x1b[1m--{name}\x1b[0m' found; no more were expected", usage=usage)
                res.values[name]=True; res.explicit.add(name); i+=1; continue
            # value option
            if not has_val:
                if i+1>=len(argv):
                    clap_error(f"a value is required for '\x1b[33m{opt_display(name)}\x1b[0m' but none was supplied")
                nxt=argv[i+1]
                if nxt.startswith('-') and nxt!='-' and len(nxt)>1:
                    # known flag / unknown handling approximation
                    # if nxt is a recognised option or -h/-V, report missing value; else report unknown arg
                    nxt_name=nxt.lstrip('-').split('=')[0]
                    if nxt_name in OPT_BY_NAME or nxt_name in ('h','V','help','version') or (len(nxt)>=2 and nxt[1] in OPT_BY_SHORT):
                        clap_error(f"a value is required for '\x1b[33m{opt_display(name)}\x1b[0m' but none was supplied")
                    else:
                        # unknown argument error for nxt
                        disp=nxt.split('=')[0]
                        sim=_similar(disp.lstrip('-'), [o2[0] for o2 in OPTS]) if disp.startswith('--') else None
                        if sim:
                            clap_error(f"unexpected argument '\x1b[33m{disp}\x1b[0m' found", usage=clap_usage_long(), tip=f"a similar argument exists: '\x1b[32m--{sim}\x1b[0m'")
                        clap_error(f"unexpected argument '\x1b[33m{disp}\x1b[0m' found", tip=f"to pass '\x1b[33m{disp}\x1b[0m' as a value, use '\x1b[32m-- {disp}\x1b[0m'")
                val=nxt; i+=2
            else:
                i+=1
            res.values[name]=validate(name,val); res.explicit.add(name); continue
        elif arg.startswith('-') and arg!='-':
            # short cluster
            chars=arg[1:]
            j=0
            consumed_next=False
            while j < len(chars):
                ch=chars[j]
                if ch=='h':
                    sys.stdout.write(data_text('help_short.txt')); raise SystemExit(0)
                if ch=='V':
                    sys.stdout.write(VERSION+"\n"); raise SystemExit(0)
                if ch not in OPT_BY_SHORT:
                    disp='-'+ch
                    clap_error(f"unexpected argument '\x1b[33m{disp}\x1b[0m' found", tip=f"to pass '\x1b[33m{disp}\x1b[0m' as a value, use '\x1b[32m-- {disp}\x1b[0m'")
                o=OPT_BY_SHORT[ch]; name=o[0]
                if name in seen:
                    clap_error(f"the argument '\x1b[33m{opt_display(name)}\x1b[0m' cannot be used multiple times")
                seen.add(name)
                if o[3]=='flag':
                    res.values[name]=True; res.explicit.add(name); j+=1; continue
                # value option as short: rest of arg is value, or next argv
                rest=chars[j+1:]
                if rest.startswith('='): rest=rest[1:]
                if rest:
                    val=rest; j=len(chars)
                else:
                    if i+1>=len(argv):
                        clap_error(f"a value is required for '\x1b[33m{opt_display(name)}\x1b[0m' but none was supplied")
                    nxt=argv[i+1]
                    if nxt.startswith('-') and nxt!='-' and len(nxt)>1:
                        clap_error(f"a value is required for '\x1b[33m{opt_display(name)}\x1b[0m' but none was supplied")
                    val=nxt; consumed_next=True; j=len(chars)
                res.values[name]=validate(name,val); res.explicit.add(name)
            i+= (2 if consumed_next else 1); continue
        else:
            res.positionals.append(arg)
            if len(res.positionals)>2:
                clap_error(f"unexpected argument '\x1b[33m{arg}\x1b[0m' found")
            i+=1; continue
    return res

# ---------------- gitconfig parsing ----------------
class GitConfig:
    def __init__(self):
        self.data={}  # (section, subsection, key) -> last value
        self.multi={} # key -> list
    def set(self, section, sub, key, value):
        k=(section.lower(), sub, key.lower())
        self.data[k]=value
        self.multi.setdefault(k,[]).append(value)
    def get(self, section, sub, key, default=None):
        return self.data.get((section.lower(),sub,key.lower()), default)
    def get_all_from_section(self, section, sub):
        out={}
        for (sec,sub2,key),val in self.data.items():
            if sec==section.lower() and sub2==sub: out[key]=val
        return out

def _parse_gitconfig_text(text, cfg, base_dir):
    # returns list of include paths encountered in order (handled by caller interleaving is approximate)
    includes=[]
    section=None; sub=None
    lines=text.splitlines()
    idx=0
    while idx < len(lines):
        raw=lines[idx]; idx+=1
        line=raw.strip()
        # continuation: git config values ending with backslash
        while line.endswith('\\') and not line.endswith('\\\\') and idx < len(lines):
            # Only for values (contains =) -- simplistic
            if '=' in line:
                line=line[:-1]+lines[idx]; idx+=1
            else: break
        if not line or line.startswith('#') or line.startswith(';'): continue
        if line.startswith('['):
            m=re.match(r'\[\s*([A-Za-z0-9_.-]+)(?:\s+"((?:[^"\\]|\\.)*)")?\s*\]', line)
            if m:
                section=m.group(1); sub=m.group(2)
                if sub is not None: sub=sub.replace('\\"','"').replace('\\\\','\\')
                continue
            else:
                # older [section.subsection] form
                m2=re.match(r'\[\s*([A-Za-z0-9_.-]+)\]', line)
                if m2:
                    sec=m2.group(1)
                    if '.' in sec:
                        section,sub=sec.split('.',1)
                    else: section,sub=sec,None
                    continue
                continue
        if section is None: continue
        if '=' in line:
            key,val=line.split('=',1); key=key.strip(); val=val.strip()
        else:
            key=line.strip(); val='true'
        # strip inline comments not in quotes / escaped
        if val and not (val.startswith('"')):
            # remove comment starting with # or ; preceded by space
            out=''; inq=False; esc=False
            for ch in val:
                if esc: out+=ch; esc=False; continue
                if ch=='\\': out+=ch; esc=True; continue
                if ch=='"': inq=not inq; out+=ch; continue
                if not inq and ch in '#;':
                    # comment if at start or preceded by whitespace in original out
                    if out=='' or out[-1] in ' \t': break
                    out+=ch
                else: out+=ch
            val=out.strip()
        # unquote / parse git config value with quotes segments
        if '"' in val:
            out=''; inq=False; esc=False
            for ch in val:
                if esc:
                    if ch=='n': out+='\n'
                    elif ch=='t': out+='\t'
                    elif ch=='b': out+='\b'
                    else: out+=ch
                    esc=False; continue
                if ch=='\\' and inq: esc=True; continue
                if ch=='"': inq=not inq; continue
                out+=ch
            val=out
        else:
            val=val.replace('\\n','\n').replace('\\t','\t')
        sec_low=section.lower()
        if sec_low=='include' and key.lower()=='path':
            includes.append(val)
        cfg.set(section, sub, key, val)
    return includes

def load_gitconfig(cli):
    cfg=GitConfig()
    if cli.values.get('no-gitconfig'):
        return cfg
    files=[]
    # system
    sys_file=os.environ.get('GIT_CONFIG_SYSTEM')
    if os.environ.get('GIT_CONFIG_NOSYSTEM'):
        pass
    elif sys_file is not None:
        if sys_file: files.append(sys_file)
    else:
        if Path('/etc/gitconfig').exists(): files.append('/etc/gitconfig')
    # global
    global_env=os.environ.get('GIT_CONFIG_GLOBAL')
    custom_config=cli.values.get('config') or ''
    if global_env is not None:
        if global_env:
            files.extend([p for p in global_env.split(os.pathsep) if p])
        # if empty, skip global
    else:
        xdg=os.environ.get('XDG_CONFIG_HOME') or str(Path.home()/'.config')
        xdg_file=str(Path(xdg)/'git'/'config')
        if Path(xdg_file).exists(): files.append(xdg_file)
        if custom_config:
            files.append(os.path.expanduser(custom_config))
        else:
            home_file=str(Path.home()/'.gitconfig')
            if True: files.append(home_file)
    seen_files=set()
    def load_file(path, depth=0):
        if depth>10: return
        try: rp=str(Path(os.path.expanduser(path)).resolve())
        except Exception: rp=path
        if rp in seen_files: return
        seen_files.add(rp)
        p=Path(os.path.expanduser(path))
        if p.is_dir():
            sys.stderr.write("Failed to read git config: requested file is a directory\n"); raise SystemExit(2)
        if not p.exists(): return
        try: text=p.read_text('utf-8','surrogateescape')
        except Exception: return
        incs=_parse_gitconfig_text(text, cfg, str(p.parent))
        for inc in incs:
            ip=inc
            if ip.startswith('~/'): ip=str(Path.home()/ip[2:])
            elif not os.path.isabs(ip): ip=str(p.parent/ip)
            load_file(ip, depth+1)
    for f in files: load_file(f)
    return cfg

