    def _custom_token(self, tok, seen):
        if tok in seen: return None
        # feature.key form
        if '.' in tok:
            feat,key=tok.split('.',1)
            sec=self.feature_sections.get(feat)
            if sec and key.lower() in sec:
                val=sec[key.lower()]
                c=parse_color_token(val.strip()) if val.strip() else None
                if c and c.kind!='rgb' or (c and len(val.strip().split())==1):
                    return c
                # if value is a style string with single color etc, parse it
                try: return parse_style(val, context=lambda t: self._custom_token(t, seen|{tok}))
                except StyleError: return c
            # also try main keys named tok?
        # known style option reference
        if tok in DEFAULTS and tok.endswith('-style'):
            return self._resolve_style_by_name(tok, seen|{tok})
        # custom keys in main / active features
        for layer in reversed(self.layers):
            if tok.lower() in layer:
                val=str(layer[tok.lower()])
                # single color?
                toks=val.split()
                if len(toks)==1:
                    c=parse_color_token(toks[0])
                    if c: return c
                try: return parse_style(val, context=lambda t: self._custom_token(t, seen|{tok}))
                except Exception: return None
            if tok in layer:
                val=str(layer[tok])
                toks=val.split()
                if len(toks)==1:
                    c=parse_color_token(toks[0])
                    if c: return c
                try: return parse_style(val, context=lambda t: self._custom_token(t, seen|{tok}))
                except Exception: return None
        # any feature section (inactive) for feature.key already handled; also plain key in any section
        for sec in self.feature_sections.values():
            if tok.lower() in sec:
                val=sec[tok.lower()]
                if len(str(val).split())==1:
                    c=parse_color_token(str(val).strip())
                    if c: return c
        return None
    def _resolve_style_by_name(self, name, seen=frozenset()):
        if name in seen: return Style()
        raw=self.raw(name)
        if raw is None:
            return Style()
        raw_s=str(raw)
        # role determines auto bg
        return self.parse_and_resolve_style(raw_s, name, seen)
    def parse_and_resolve_style(self, raw_s, role, seen=frozenset()):
        raw_s=raw_s.strip()
        # whole string reference to another style
        if raw_s in DEFAULTS and raw_s.endswith('-style') and raw_s!=role:
            return self._resolve_style_by_name(raw_s, seen|{role})
        if raw_s in self.main or raw_s.lower() in self.main:
            # custom style reference as whole string
            res=self._custom_token(raw_s, seen)
            if isinstance(res, Style): return self._resolve_auto(res, role)
        is_decoration = role.endswith('-decoration-style') or role in ('merge-conflict-ours-diff-header-decoration-style','merge-conflict-theirs-diff-header-decoration-style')
        is_element = role in ('commit-style','file-style','hunk-header-style')
        try:
            st=parse_style(raw_s, context=lambda t: self._custom_token(t, seen), decoration=is_decoration, element=is_element)
        except StyleError as e:
            sys.stderr.write(str(e)+"\n"); raise SystemExit(2)
        st=self._resolve_auto(st, role)
        return st
    def _resolve_auto(self, st, role):
        # fg auto -> normal, bg auto -> palette by role
        if st.fg is not None and st.fg.kind=='auto':
            st.fg=Color('none')
        if st.bg is not None and st.bg.kind=='auto':
            if role in ('minus-style','minus-non-emph-style','minus-empty-line-marker-style'):
                st.bg=Color('rgb', rgb=self.pal['minus_bg'])
            elif role=='minus-emph-style':
                st.bg=Color('rgb', rgb=self.pal['minus_emph_bg'])
            elif role in ('plus-style','plus-non-emph-style','plus-empty-line-marker-style'):
                st.bg=Color('rgb', rgb=self.pal['plus_bg'])
            elif role=='plus-emph-style':
                st.bg=Color('rgb', rgb=self.pal['plus_emph_bg'])
            else:
                st.bg=Color('none')
        # for display purposes in show-config, RGB bg colors that came from palette show as numbers (handled by Color.display according to truecolor)
        return st
