def to_bool(v):
    if isinstance(v,bool): return v
    if v is None: return False
    s=str(v).strip().lower()
    if s in ('true','yes','on','1',''): return True
    if s in ('false','no','off','0'): return False
    return False

class Config:
    def __init__(self, cli, gitcfg):
        self.cli=cli; self.git=gitcfg
