            if sec=='delta' and sub is not None:
                feature_sections.setdefault(sub,{})[key]=val
        self.feature_sections=feature_sections
        # git features
        feat_raw=main.get('features', main.get('feature'))
        features=feat_raw.split() if isinstance(feat_raw,str) and feat_raw.strip() else []
        if 'features' in cli.explicit:
            fv=cli.values.get('features') or ''
            features=fv.split() if str(fv).strip() else []
        env_feat=os.environ.get('DELTA_FEATURES')
        if env_feat is not None:
            if env_feat.startswith('+'):
                rest=env_feat[1:]
                features=features + (rest.split() if rest.strip() else [])
            else:
                features=env_feat.split() if env_feat.strip() else []
        self.features=features
        # builtin activations from flags
        self.flag_features=[]
        for fn in ('raw','color-only','diff-highlight','diff-so-fancy'):
            if cli.values.get(fn): self.flag_features.append(fn)
        # effective source resolution function
        # builtins layers: features in order (builtin presets) + flag features (as lowest layers, before git features?)
        # We will construct layer list (low to high): builtin/feature dicts, then main, then CLI
        self._validate_dark_light_pre()
        # determine light mode early (needed for builtin preset values which contain numeric bg refs like 52 - they are dark-specific? diff-so-fancy uses 52/22 fixed numbers, fine)
        self.is_light=self._determine_light()
        pal=self._palette()
        self.pal=pal
        # layers
        self.layers=[]  # list of dicts raw
        # flag builtin first (lowest among builtins)
        for fn in self.flag_features:
            self.layers.append(builtin_preset(fn,pal))
        for fname in self.features:
            if fname in BUILTIN_FEATURES:
                self.layers.append(builtin_preset(fname,pal))
            if fname in self.feature_sections:
                self.layers.append(self.feature_sections[fname])
        # main layer
        self.layers.append(main)
        # cli layer converted to raw strings
        cli_layer={}
        for k,v in cli.values.items():
            if k in ('features',): continue
            cli_layer[k]=v
        self.layers.append(cli_layer)
        # NOTE layers above include defaults separately
        self._resolve_all()
    def _raw_and_source(self, name):
        # returns (raw, source) highest priority layer containing name, else default
        # CLI is last layer
        for idx in range(len(self.layers)-1,-1,-1):
            layer=self.layers[idx]
            if name in layer:
                src='cli' if idx==len(self.layers)-1 else ('main' if layer is self.main else 'feature')
                return layer[name], src
        return DEFAULTS.get(name), 'default'
    def raw(self,name):
        return self._raw_and_source(name)[0]
    def source(self,name):
        return self._raw_and_source(name)[1]
    def user_supplied(self,name):
        return self.source(name) in ('cli','main','feature')
    def get_str(self,name, default=None):
        v=self.raw(name)
        if v is None: return default
        return str(v)
    def get_bool(self,name):
        return to_bool(self.raw(name))
    def get_int(self,name, default=0):
