            ws_style_str=None
            # git config: [color] diff = ??? Actually [color "diff"] whitespace = ...
            wsv=self.git.data.get(('color','diff','whitespace'))
            if wsv: ws_style_str=wsv
            else: ws_style_str='magenta reverse'
            self.styles['whitespace-error-style']=self.parse_and_resolve_style(ws_style_str,'whitespace-error-style')
        else:
            # if user supplied "auto auto", fg/bg auto resolution for whitespace gives? Treat as default magenta reverse if exactly auto auto?
            if str(ws_raw).strip()=='auto auto':
                self.styles['whitespace-error-style']=self.parse_and_resolve_style('magenta reverse','whitespace-error-style')
            else:
                self.styles['whitespace-error-style']=self.parse_and_resolve_style(str(ws_raw),'whitespace-error-style')
        for name in ['commit-decoration-style','file-decoration-style','hunk-header-decoration-style','hunk-header-file-style','hunk-header-line-number-style','blame-separator-style','merge-conflict-ours-diff-header-decoration-style','merge-conflict-ours-diff-header-style','merge-conflict-theirs-diff-header-decoration-style','merge-conflict-theirs-diff-header-style','grep-header-decoration-style','grep-header-file-style']:
            rawv=self.raw(name)
            if rawv is None:
                # defaults for some handled later
                self.styles[name]=None
            else:
                self.styles[name]=self.parse_and_resolve_style(str(rawv), name)
        # explicit decoration styles defaults if None (they have defaults in DEFAULTS so raw is not None for main ones)
        # blame palette
        bp_raw=self.raw('blame-palette')
        if bp_raw is None:
            self.blame_palette=[parse_color_token(x) for x in self.pal['blame']]
            self.blame_palette_raw=self.pal['blame']
        else:
            toks=str(bp_raw).split()
            cols=[]
            for t in toks:
                c=self._custom_token(t,frozenset())
                if isinstance(c,Color): cols.append(c); continue
                c=parse_color_token(t)
                if c is None:
                    sys.stderr.write(f"Invalid color or style attribute: {t}\n"); raise SystemExit(2)
                cols.append(c)
            self.blame_palette=cols; self.blame_palette_raw=toks
        # side-by-side transforms
        self.side_by_side=self.get_bool('side-by-side')
        self.line_numbers_user=self.get_bool('line-numbers')
        self.line_numbers=self.line_numbers_user or self.side_by_side
        # line number formats/styles resolution deferred but compute now
        self._resolve_line_numbers()
        # navigate regex default
        nav=self.get_bool('navigate')
        self.navigate=nav
        if nav:
            # file-modified-label transformation: default '' becomes ' Δ' in navigate mode per show-config (file-modified-label = ' Δ')
            pass
        # derived style fallbacks for grep etc after main styles
        # color-only / raw / diff modes
        self.color_only_mode = ('color-only' in self.flag_features) or ('color-only' in self.features and 'color-only' in BUILTIN_FEATURES) or self.get_bool('color-only')
        # Actually get_bool('color-only') returns CLI flag / feature true; raw also sets structural mode via separate flag
        self.raw_mode = ('raw' in self.flag_features) or ('raw' in self.features) or self.cli.values.get('raw',False)
        self.diff_highlight_mode = ('diff-highlight' in self.flag_features) or ('diff-highlight' in self.features)
        self.diff_so_fancy_mode = ('diff-so-fancy' in self.flag_features) or ('diff-so-fancy' in self.features)
        # mode booleans from CLI flags directly also
        if self.cli.values.get('color-only'): self.color_only_mode=True
        if self.cli.values.get('diff-highlight'): self.diff_highlight_mode=True
        if self.cli.values.get('diff-so-fancy'): self.diff_so_fancy_mode=True
        # In color-only structural mode if also raw? raw preset governs styles; structural classification done in render
        # keep plus minus effective
        self.keep_plus_minus=self.get_bool('keep-plus-minus-markers')
