        rawv=self.raw(name)
        if rawv is None:
            if name=='grep-context-line-style': return self._resolve_style_by_name('zero-style')
            if name=='grep-match-line-style': return self._resolve_style_by_name('plus-style')
            if name=='grep-match-word-style': return self._resolve_style_by_name('plus-style')
            if name=='blame-code-style': return None
            return Style()
        return self.parse_and_resolve_style(str(rawv), name)
    def _parse_width(self,w):
        w=w.strip()
        # negative
        if w.startswith('-') and re.fullmatch(r'-\d+', w):
            mag=int(w[1:])
            if mag>self.terminal_width_val:
                sys.stderr.write(f"Invalid value for width: the current terminal width of {self.terminal_width_val} minus {mag} is negative\n"); raise SystemExit(2)
            return self.terminal_width_val-mag
        if '-' in w[1:]:
            parts=w.split('-')
            if len(parts)==2:
                try:
                    a=int(parts[0]); b=int(parts[1])
                except Exception:
                    sys.stderr.write(f'Invalid value for width: "{w}" is not an integer\n'); raise SystemExit(2)
                res=a-b
                if res<=0:
                    sys.stderr.write(f'Invalid value for width: expression "{w}" is not positive\n'); raise SystemExit(2)
                return res
        try:
            return int(w)
        except Exception:
            sys.stderr.write(f'Invalid value for width: "{w}" is not an integer\n'); raise SystemExit(2)
    def _validate_custom(self):
        # width already handled before this if width set; wrap options
        wml=self.get_str('wrap-max-lines','2')
        if wml!='unlimited':
            if not re.fullmatch(r'\d+', str(wml).strip()):
                sys.stderr.write("Invalid wrap-max-lines argument: invalid digit found in string\n"); raise SystemExit(2)
        wrp=self.get_str('wrap-right-percent','37.0')
        try: fv=float(str(wrp))
        except Exception:
            sys.stderr.write(f"Could not parse wrap-right-percent argument {wrp}: invalid float literal.\n"); raise SystemExit(2)
        if not (0 <= fv <= 100):
            sys.stderr.write("Invalid value for wrap-right-percent, not between 0 and 100.\n"); raise SystemExit(2)
        # regex validations (commit-regex, word-diff-regex immediate; navigate-regex only if navigate?)
        for optname in ('commit-regex','word-diff-regex'):
            pat=self.get_str(optname,'')
            if pat:
                try: re.compile(pat)
                except Exception:
                    sys.stderr.write(f"Invalid {optname}: {pat}. The value must be a valid Rust regular expression. See https://docs.rs/regex.\n"); raise SystemExit(2)
    def _resolve_line_numbers(self):
        # styles
        self.ln_styles={}
        # default palette for auto in dark/light
        if self.is_light:
            auto_colors={'minus':(160,0,0),'zero':(128,128,128),'plus':(0,128,0)} # placeholder refined later
            # Actual light values probed later
            minus_c=Color('rgb', rgb=(218, 100, 100)) # dummy
        # Use observed dark fixed values; light probed separately (fallback to same logic via theme?)
        # We'll compute from known mapping: dark minus 88, zero 238, plus 28
        def auto_style(kind):
            st=Style()
            if kind=='minus': st.fg=Color('fixed',88)
            elif kind=='plus': st.fg=Color('fixed',28)
            else: st.fg=Color('fixed',238)
            return st
        for name,kind in [('line-numbers-minus-style','minus'),('line-numbers-zero-style','zero'),('line-numbers-plus-style','plus')]:
            rawv=self.raw(name)
            if rawv is None or str(rawv).strip()=='auto':
                self.ln_styles[name]=auto_style(kind)
            else:
                self.ln_styles[name]=self.parse_and_resolve_style(str(rawv), name)
        for name in ['line-numbers-left-style','line-numbers-right-style']:
            rawv=self.raw(name)
            if rawv is None or str(rawv).strip()=='auto':
                st=Style(); st.fg=Color('ansi',4); self.ln_styles[name]=st
            else:
                self.ln_styles[name]=self.parse_and_resolve_style(str(rawv), name)
        # side-by-side formats override if not user supplied
        self.ln_left_format=self.get_str('line-numbers-left-format','{nm:^4}⋮')
        self.ln_right_format=self.get_str('line-numbers-right-format','{np:^4}│')
        if self.side_by_side:
            if self.source('line-numbers-left-format')=='default': self.ln_left_format='│{nm:^4}│'
            if self.source('line-numbers-right-format')=='default': self.ln_right_format='│{np:^4}│'
            # minus styles fg syntax transform if not user supplied for that style
            for nm in ('minus-style','minus-non-emph-style','minus-emph-style'):
                if not self.user_supplied(nm):
                    st=self.styles.get(nm)
                    if st and (st.fg is None or st.fg.kind=='none'):
                        st.fg=Color('syntax')
        # hyperlinks etc
    def style_display(self,name):
        st=self.styles.get(name)
        if st is None: return ''
        return st.display_string(self.true_color)

