# ---------------- utilities ----------------
def disp_width(s):
    w=0
    for ch in s:
        if unicodedata.combining(ch): continue
        if ord(ch)<32: continue
        w+= 2 if unicodedata.east_asian_width(ch) in ('W','F') else 1
    return w

def expand_tabs(s, tab_width):
    if tab_width==0:
        return s
    out=[]; col=0
    for ch in s:
        if ch=='\t':
            n=tab_width - (col % tab_width) if tab_width>0 else 0
            out.append(' '*n); col+=n
        else:
            out.append(ch); col+=disp_width(ch)
    return ''.join(out)

ANSI_RE=re.compile(r'\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[@-Z\\-_]')
def strip_ansi(s):
    return ANSI_RE.sub('', s)

class EffStyle:
    __slots__=('fg','bg','attrs')
    def __init__(self, fg=None,bg=None,attrs=frozenset()):
        self.fg=fg; self.bg=bg; self.attrs=frozenset(attrs)
    def __eq__(self,o): return isinstance(o,EffStyle) and self.fg==o.fg and self.bg==o.bg and self.attrs==o.attrs
    def __hash__(self): return hash((self.fg,self.bg,self.attrs))
    def prefix(self, true_color):
        params=[]
        for a in sorted(self.attrs, key=lambda x: ATTR_CODES[x]): params.append(str(ATTR_CODES[a]))
        if self.bg is not None:
            c=self.bg.sgr(True,true_color)
            if c: params.append(c)
        if self.fg is not None:
            c=self.fg.sgr(False,true_color)
            if c: params.append(c)
        return ('\x1b['+';'.join(params)+'m') if params else ''
    def is_empty(self): return self.fg is None and self.bg is None and not self.attrs

def style_to_eff(st, syntax_color=None):
    """Convert a Style to EffStyle; syntax_color Color or None replaces fg if fg is syntax.
       If fg is syntax and syntax_color is None, fg becomes None."""
    if st is None: return EffStyle()
    fg=st.fg; bg=st.bg
    if fg is not None and fg.kind=='syntax':
        fg=syntax_color
    if fg is not None and fg.kind in ('none','auto'): fg=None
    if fg is not None and fg.kind=='raw_special': fg=None
    if bg is not None and bg.kind in ('none','auto'): bg=None
    if bg is not None and bg.kind=='syntax': bg=None
    return EffStyle(fg,bg,st.attrs)

def paint_segments(segments, true_color):
    """segments: list of (text, EffStyle). ANSIStrings-like transition logic."""
    out=[]; cur=EffStyle()
    for text, eff in segments:
        if not text: continue
        if eff==cur:
            out.append(text); continue
        # can transition without reset? need: no attr removal, no fg/bg removal
        need_reset=False
        if not cur.attrs.issubset(eff.attrs): need_reset=True
        if cur.fg is not None and eff.fg is None: need_reset=True
        if cur.bg is not None and eff.bg is None: need_reset=True
        if need_reset:
            if not cur.is_empty(): out.append('\x1b[0m')
            if not eff.is_empty(): out.append(eff.prefix(true_color))
        else:
            # emit only differing components in order attrs-added, bg, fg
            params=[]
            for a in sorted(eff.attrs-cur.attrs, key=lambda x: ATTR_CODES[x]): params.append(str(ATTR_CODES[a]))
            if eff.bg!=cur.bg and eff.bg is not None:
                c=eff.bg.sgr(True,true_color)
                if c: params.append(c)
            if eff.fg!=cur.fg and eff.fg is not None:
                c=eff.fg.sgr(False,true_color)
                if c: params.append(c)
            if params: out.append('\x1b['+';'.join(params)+'m')
        out.append(text); cur=eff
    return ''.join(out), cur

def paint_single(text, eff, true_color):
    if eff.is_empty(): return text
    return eff.prefix(true_color)+text+'\x1b[0m'

