def theme_color(theme_name, cat):
    if theme_name=='none': return None
    if theme_name=='ansi':
        m={'fg':None,'keyword':'magenta','string':'green','comment':'green','number':None,'function':'blue','type':'yellow','builtin':'cyan','variable':None,'constant':None,'operator':'magenta'}
        v=m.get(cat)
        if v is None:
            # defaults: fg none
            return None
        return Color('ansi', ANSI_NAMES[v])
    if theme_name in ('base16','base16-256'):
        # approximate ansi_term output observed: keyword magenta(35), func blue, string splits quotes?
        m={'keyword':Color('ansi',5),'string':Color('ansi',2),'comment':Color('fixed',8),'number':Color('fixed',9),'function':Color('ansi',4),'type':Color('ansi',6),'builtin':Color('ansi',6),'operator':Color('ansi',5),'fg':Color('ansi',7),'variable':Color('ansi',7),'constant':Color('fixed',9)}
        return m.get(cat, Color('ansi',7))
    pal=THEMES.get(theme_name) or THEMES['Monokai Extended']
    hexv=pal.get(cat, pal.get('fg'))
    return C_rgb(hexv) if hexv else None

def detect_language(filename, default_lang='txt', first_line=''):
    if first_line.startswith('#!'):
        fl=first_line.lower()
        if 'python' in fl: return 'python'
        if 'ruby' in fl: return 'ruby'
        if 'node' in fl: return 'javascript'
        if 'bash' in fl or fl.rstrip().endswith('sh'): return 'shell'
        if 'perl' in fl: return 'perl'
    if not filename:
        return default_lang
    base=os.path.basename(filename)
    ext=base.rsplit('.',1)[-1].lower() if '.' in base else ''
    special={'makefile':'make','dockerfile':'docker','cmakelists.txt':'cmake','go.mod':'go','cargo.toml':'toml','cargo.lock':'toml'}
    if base.lower() in special: return special[base.lower()]
    m={'py':'python','pyw':'python','rs':'rust','js':'javascript','mjs':'javascript','cjs':'javascript','jsx':'javascript','ts':'typescript','tsx':'typescript','java':'java','kt':'kotlin','scala':'scala','c':'c','h':'c','cpp':'cpp','cc':'cpp','cxx':'cpp','hpp':'cpp','cs':'csharp','go':'go','rb':'ruby','sh':'shell','bash':'shell','zsh':'shell','php':'php','html':'html','htm':'html','css':'css','scss':'css','json':'json','yaml':'yaml','yml':'yaml','toml':'toml','xml':'xml','md':'markdown','markdown':'markdown','sql':'sql','lua':'lua','pl':'perl','pm':'perl','r':'r','swift':'swift','m':'objc','mm':'objc','ex':'elixir','exs':'elixir','erl':'erlang','hs':'haskell','ml':'ocaml','clj':'clojure','groovy':'groovy','gradle':'groovy','vim':'vim','diff':'diff','patch':'diff','tex':'latex','txt':'txt','text':'txt','rs':'rust'}
    if ext in m: return m[ext]
    # use default language name translation
    dl=(default_lang or 'txt').lower()
    rev={v:k for k,v in m.items()}
    if dl in ('txt','text','plain text'): return 'txt'
    if dl in m and False: pass
    # default_lang may be a language name like "Rust" or extension
    name_map={'python':'python','rust':'rust','javascript':'javascript','typescript':'typescript','java':'java','c':'c','c++':'cpp','cpp':'cpp','go':'go','ruby':'ruby','bash':'shell','shell':'shell','bourne again shell (bash)':'shell'}
    if dl in name_map: return name_map[dl]
    if dl in m: return m[dl]
    return 'txt'

class Highlighter:
    def __init__(self, cfg, filename):
        self.cfg=cfg; self.filename=filename
        self.lang=detect_language(filename, cfg.get_str('default-language','txt'))
        self.theme=cfg.syntax_theme if not cfg.no_syntax else 'none'
        self.in_block_comment=False; self.in_triple=None; self.in_template=False
    def color(self,cat):
        if self.cfg.no_syntax: return None
        # max syntax length handled by caller truncating syntax at char level
        return theme_color(self.theme, cat)
    def highlight(self, line):
        """returns list of (text, Color|None)"""
        if self.cfg.no_syntax or self.lang=='txt':
            return [(line, self.color('fg'))] if line else []
        lang=self.lang
        segs=[]; i=0; n=len(line)
        def emit(text,cat):
            if not text: return
            c=self.color(cat)
            if segs and segs[-1][1]==c: segs[-1]=(segs[-1][0]+text,c)
            else: segs.append((text,c))
        # state handling at line start
        prev_token=''
        while i<n:
            if self.in_block_comment:
                end=line.find('*/',i)
                if end==-1: emit(line[i:],'comment'); i=n
                else: emit(line[i:end+2],'comment'); i=end+2; self.in_block_comment=False
                continue
            if self.in_triple:
                end=line.find(self.in_triple,i)
                if end==-1: emit(line[i:],'string'); i=n
                else: emit(line[i:end+3],'string'); i=end+3; self.in_triple=None
                continue
            if self.in_template:
                end=line.find('`',i)
                if end==-1: emit(line[i:],'string'); i=n
                else: emit(line[i:end+1],'string'); i=end+1; self.in_template=False
                continue
            ch=line[i]
            # comments
            if lang in ('python','ruby','shell','perl','yaml','toml','r') and ch=='#' and (lang!='python' or True):
                # in python # is comment anywhere outside string
                emit(line[i:],'comment'); break
            if lang not in ('python','ruby','shell','perl','yaml','toml','r') and line.startswith('//',i):
                emit(line[i:],'comment'); break
            if lang not in ('python','ruby','shell') and line.startswith('/*',i):
                end=line.find('*/',i+2)
                if end==-1: emit(line[i:],'comment'); self.in_block_comment=True; break
                else: emit(line[i:end+2],'comment'); i=end+2; continue
            if lang=='html' and line.startswith('<!--',i):
                emit(line[i:],'comment'); break
            # Python triple strings
            if lang=='python' and (line.startswith('"""',i) or line.startswith("'''",i)):
                q=line[i:i+3]; end=line.find(q,i+3)
                if end==-1: emit(line[i:],'string'); self.in_triple=q; break
                else: emit(line[i:end+3],'string'); i=end+3; continue
            # strings
            if ch in ('"',"'",'`'):
                # C char literal etc treated string
                q=ch; j=i+1
                if q=='`' and lang in ('javascript','typescript','go'):
                    pass
                while j<n:
                    if line[j]=='\\' and q!='`': j+=2; continue
                    if line[j]==q: j+=1; break
                    j+=1
                else:
                    if q=='`' and lang in ('javascript','typescript'): self.in_template=True
                emit(line[i:j],'string'); i=j; prev_token='string'; continue
            # numbers
            m=re.match(r'(0[xX][0-9a-fA-F_]+|\d[\d_]*(?:\.\d[\d_]*)?(?:[eE][+-]?\d+)?)', line[i:])
            if m and (i==0 or not (line[i-1].isalnum() or line[i-1]=='_')):
                emit(m.group(0),'number'); i+=len(m.group(0)); prev_token='number'; continue
            # preprocessor in C-like
            if ch=='#' and i==0 and lang in ('c','cpp'):
                emit(line[i:],'keyword'); break
            # identifiers
            m=re.match(r'[A-Za-z_][A-Za-z0-9_]*', line[i:])
            if m:
                word=m.group(0); end=i+len(word)
                # look ahead nonspace char
                k=end
                while k<n and line[k]==' ': k+=1
                nxt=line[k] if k<n else ''
                keywords=LANG_KEYWORDS.get(lang,set())
                builtins=LANG_BUILTINS.get(lang,set())
                if prev_token in ('def','fn','func','function'):
                    cat='function'
                elif prev_token in ('class','struct','interface','enum','trait','type'):
                    cat='type'
                elif word in keywords:
                    cat='keyword'
                    # in some themes 'function' keyword in JS colored type; handled generically: keep keyword
                    if lang in ('javascript','typescript') and word=='function': cat='type'
                elif word in builtins:
                    cat='builtin' if lang!='python' and word not in ('print',) else ('builtin' if word in ('print',) else 'type')
                    if lang=='python' and word[0].isupper(): cat='type'
                    if lang=='rust' and word[0].isupper(): cat='type'
                elif word[0].isupper():
                    cat='type'
                elif nxt=='(':
                    cat='function' if lang not in ('python',) else 'fg'
                    # In Python, function calls are fg (syntect Python: support.function?) observed foo() at call? def name green, call (?) In example.rs println etc. For python `foo()` in zero line? Only def sample. Keep: python calls fg except builtins
                    if lang=='python': cat='fg'
                elif word.isupper() and len(word)>1:
                    cat='constant'
                else:
                    cat='fg'
                emit(word,cat); prev_token=word; i=end; continue
            # operators / punctuation
            if ch in '=<>!&|+-*/%?:':
                # multi char operators
                m=re.match(r'(==|!=|<=|>=|&&|\|\||\+=|-=|\*=|/=|=>|->|::|\+\+|--|:=)', line[i:])
                txt=m.group(0) if m else ch
                # colon only operator in some contexts? syntect keeps punctuation fg mostly
                if ch==':':
                    emit(ch,'fg'); i+=1; prev_token=':'; continue
                emit(txt,'operator'); i+=len(txt); prev_token='op'; continue
            # whitespace and punctuation as fg
            emit(ch,'fg')
            if not ch.isspace(): prev_token=ch
            i+=1
        return segs

