# ---------------- token alignment ----------------
def tokenize(line, word_regex):
    try: pat=re.compile(word_regex)
    except Exception: pat=re.compile(r'\w+')
    toks=[]; pos=0
    for m in pat.finditer(line):
        if m.start()>pos: toks.append((line[pos:m.start()], False))
        if m.end()>m.start(): toks.append((m.group(0), True))
        pos=m.end()
    if pos<len(line): toks.append((line[pos:], False))
    return toks

def token_align(minus_line, plus_line, word_regex):
    mt=tokenize(minus_line, word_regex); pt=tokenize(plus_line, word_regex)
    m=len(mt); n=len(pt)
    # DP
    INF=10**9
    dp=[[0]*(n+1) for _ in range(m+1)]
    for i in range(1,m+1): dp[i][0]=i
    for j in range(1,n+1): dp[0][j]=j
    for i in range(1,m+1):
        for j in range(1,n+1):
            cost=0 if mt[i-1][0]==pt[j-1][0] else 1
            dp[i][j]=min(dp[i-1][j-1]+cost, dp[i-1][j]+1, dp[i][j-1]+1)
    mem=[False]*m; pep=[False]*n
    i,j=m,n
    while i>0 or j>0:
        if i>0 and j>0 and dp[i][j]==dp[i-1][j-1]+(0 if mt[i-1][0]==pt[j-1][0] else 1):
            if mt[i-1][0]!=pt[j-1][0]: mem[i-1]=True; pep[j-1]=True
            i-=1; j-=1
        elif i>0 and (j==0 or dp[i][j]==dp[i-1][j]+1):
            mem[i-1]=True; i-=1
        elif j>0:
            pep[j-1]=True; j-=1
        else: break
    # coalesce emph separated only by whitespace token(s)
    def coalesce(toks, emph):
        emph=emph[:]
        for k in range(1,len(toks)-1):
            if not emph[k] and toks[k][0].strip()=='' and emph[k-1] and emph[k+1]:
                emph[k]=True
        return emph
    mem=coalesce(mt,mem); pep=coalesce(pt,pep)
    # char ranges
    def to_ranges(toks, emph):
        arr=[]; pos=0
        for (txt,isw),e in zip(toks,emph):
            arr.extend([e]*len(txt)); pos+=len(txt)
        return arr
    # distance based on word tokens only
    def word_stats(toks, emph):
        changed=0; total=0
        for (txt,isw),e in zip(toks,emph):
            if isw:
                total+=len(txt)
                if e: changed+=len(txt)
        return changed,total
    mc,mtot=word_stats(mt,mem); pc,ptot=word_stats(pt,pep)
    if mtot+ptot==0:
        # fallback char distance
        dist=0.0 if minus_line==plus_line else 1.0
    else:
        dist=(mc+pc)/(mtot+ptot) if (mtot+ptot) else 1.0
    return to_ranges(mt,mem), to_ranges(pt,pep), dist, (any(mem), any(pep))

def pair_lines(minus_texts, plus_texts, cfg):
    """returns dict minus_index->(plus_index, minus_emph, plus_emph), and plus_index->... via that dict"""
    m=len(minus_texts); n=len(plus_texts)
    if m==0 or n==0: return {}
    aligns={}
    dists={}
    for i,a in enumerate(minus_texts):
        for j,b in enumerate(plus_texts):
            me,pe,d,has=token_align(a,b,cfg.get_str('word-diff-regex',r'\w+'))
            aligns[(i,j)]=(me,pe); dists[(i,j)]=d
    maxd=cfg.get_float('max-line-distance',0.6)
    # DP monotonic
    # dp over i,j min cost; pair cost = dist, skip cost = 0.65 (tunable > max dist)
    SKIP=0.65
    dp=[[0.0]*(n+1) for _ in range(m+1)]
    choice=[[None]*(n+1) for _ in range(m+1)]
    for i in range(1,m+1): dp[i][0]=i*SKIP; choice[i][0]='m'
    for j in range(1,n+1): dp[0][j]=j*SKIP; choice[0][j]='p'
    for i in range(1,m+1):
        for j in range(1,n+1):
            candidates=[]
            d=dists[(i-1,j-1)]
            if d <= maxd+1e-12:
                candidates.append((dp[i-1][j-1]+d, 'pair'))
            candidates.append((dp[i-1][j]+SKIP, 'm'))
            candidates.append((dp[i][j-1]+SKIP, 'p'))
            # tie-breaking: prefer pair, then skip plus (p) over skip minus (m) as observed?
            order={'pair':0,'p':1,'m':2}
            candidates.sort(key=lambda x:(round(x[0],12), order[x[1]]))
            dp[i][j]=candidates[0][0]; choice[i][j]=candidates[0][1]
    pairs={}
    i,j=m,n
    while i>0 or j>0:
        c=choice[i][j] if (i>0 or j>0) else None
        if i==0: c='p'
        if j==0: c='m'
        if c=='pair':
            me,pe=aligns[(i-1,j-1)]
            pairs[i-1]=(j-1,me,pe)
            i-=1; j-=1
        elif c=='m': i-=1
        elif c=='p': j-=1
        else: break
    return pairs

# ---------------- decoration / headers ----------------
def paint_decorated(segments, dec_style, cfg, force_box=False):
    """segments list (text, EffStyle). dec_style Style or None. Returns list of output lines (strings without newline)"""
    # compute visible text
    if dec_style is None and not force_box:
        text,_=paint_segments(segments, cfg.true_color)
        # need reset if ended in style
        # paint_segments returns current; caller handles? We'll use helper below
        return [_finish_painted(segments,cfg)]
    kind=None; core=EffStyle()
    if dec_style is not None:
        kind=dec_style.decoration
        core=style_to_eff(dec_style)
        # decoration style attrs may contain(?) bold remains; ul removed in parse
    if force_box: kind='box'
    if kind is None or kind=='none':
        return [_finish_painted(segments,cfg)]
    bold='bold' in (dec_style.attrs if dec_style else set())
    horiz='━' if bold else '─'
    if kind=='box':
        vchar='┃' if bold else '│'; tr='┓' if bold else '┐'; br='┛' if bold else '┘'
        total=disp_width(''.join(t for t,_ in segments))+1
        top=paint_single(horiz*total, core, cfg.true_color)+paint_single(tr, core, cfg.true_color)
        bottom=paint_single(horiz*total, core, cfg.true_color)+paint_single(br, core, cfg.true_color)
        # middle: append space to last segment
        segs=[(t,e) for t,e in segments]
        if segs: segs[-1]=(segs[-1][0]+' ', segs[-1][1])
        else: segs=[(' ',EffStyle())]
        middle=_finish_painted(segs,cfg)+paint_single(vchar, core, cfg.true_color)
        return [top, middle, bottom]
    # ul / ol
    width=cfg.width_val if cfg.width_val is not None else disp_width(''.join(t for t,_ in segments))
    line=paint_single(horiz*width, core, cfg.true_color)
    mid=_finish_painted(segments,cfg)
    out=[]
    if kind in ('ol','ul ol'): out.append(line)
    out.append(mid)
    if kind in ('ul','ul ol'): out.append(line)
    return out

def _finish_painted(segments,cfg):
    txt,cur=paint_segments(segments,cfg.true_color)
    if not cur.is_empty(): txt+='\x1b[0m'
    return txt

def format_placeholder(fmt, values):
    """values dict name->str or None. Returns list of (text, is_placeholder, name) segments to allow styling numbers separately.
       Simpler: returns rendered string and spans of placeholder values as (start,end,name)"""
    out=''; spans=[]; i=0
    while i < len(fmt):
        if fmt[i]=='{' :
            end=fmt.find('}',i)
            if end==-1: out+=fmt[i]; i+=1; continue
            inner=fmt[i+1:end]
            if ':' in inner: name,spec=inner.split(':',1)
            else: name,spec=inner,''
            if name not in values:
                out+=fmt[i:end+1]; i=end+1; continue
            val=values[name] if values[name] is not None else ''
            # parse spec: fill/align width .precision
            fill=' '; align=None; width=None; prec=None
            s=spec
            # precision
            if '.' in s:
                s,ps=s.split('.',1)
                if ps.isdigit(): prec=int(ps)
            if len(s)>=2 and s[1] in '<^>': fill=s[0]; align=s[1]; s=s[2:]
            elif len(s)>=1 and s[0] in '<^>': align=s[0]; s=s[1:]
            if s.isdigit(): width=int(s)
            if prec is not None: val=val[:prec]
            if width is not None:
                if align=='<': rendered=val.ljust(width,fill)
                elif align=='>': rendered=val.rjust(width,fill)
                elif align=='^':
                    # Rust center: extra padding goes to right? Python center similar but check: for width 4, "1" -> " 1  " in Rust? Observed "  1 " for {nm:^4} with 1: that is left pad 2? Wait format output "  1 " has 2 left,1 right (total4). Python center gives " 1  " (1 left 2 right). Rust formatting centers with extra on left? Actually Rust: format!("{:^4}",1) -> " 1  "? Need check observed: line-numbers format gave '  1 ' (two spaces before, one after). That's Rust center alignment where padding is split with larger on left when odd.
                    total=width-len(val)
                    if total>0:
                        left=(total+1)//2; right=total-left; rendered=fill*left+val+fill*right
                    else: rendered=val
                else: rendered=val.ljust(width,fill)  # default for strings left, numbers? Rust default align for numbers is right, but placeholder values are strings formed from numbers? delta passes numbers as integers to format, default align would be right for numeric.
                    # The above default branch is unreachable for spec without align but width: use right for numeric strings
                    if val.isdigit(): rendered=val.rjust(width,fill)
            else: rendered=val
            start=len(out); out+=rendered; spans.append((start,len(out),name)); i=end+1
        else:
            out+=fmt[i]; i+=1
    return out, spans

