# ---------------- token alignment ----------------
def tokenize(line, word_regex):
    try: pat=re.compile(word_regex)
    except Exception: pat=re.compile(r'\w+')
    toks=[]; pos=0
    for m in pat.finditer(line):
        if m.start()>pos: toks.append((line[pos:m.start()], False))
        if m.end()>m.start(): toks.append((m.group(0), True))
        pos=m.end()
    if pos<len(line): toks.append((line[pos:], False))
    return toks

