    for j in range(1,n+1): dp[0][j]=j
    for i in range(1,m+1):
        for j in range(1,n+1):
            cost=0 if mt[i-1][0]==pt[j-1][0] else 1
            dp[i][j]=min(dp[i-1][j-1]+cost, dp[i-1][j]+1, dp[i][j-1]+1)
