        if i>0 and j>0 and dp[i][j]==dp[i-1][j-1]+(0 if mt[i-1][0]==pt[j-1][0] else 1):
            if mt[i-1][0]!=pt[j-1][0]: mem[i-1]=True; pep[j-1]=True
            i-=1; j-=1
        elif i>0 and (j==0 or dp[i][j]==dp[i-1][j]+1):
            mem[i-1]=True; i-=1
