def unquote_path(s):
    s=s.strip()
    if len(s)>=2 and s[0]=='"' and s[-1]=='"':
        try:
            return bytes(s[1:-1],'utf-8').decode('unicode_escape')
        except Exception:
            return s[1:-1]
    return s
