    if path=='/dev/null': return path
    prefixes=('a/','i/','c/') if is_minus else ('b/','w/','c/')
    # also strip a/ for plus in weird i/w cases from +++ line: git uses b/, but mnemonic plus is w/
    for p in prefixes:
