    # quoted tokens
    toks=re.findall(r'"((?:[^"\\]|\\.)*)"|\S+', rest)
    # findall returns group for quoted or '' ; reconstruct via shlex
    try:
        parts=shlex.split(rest)
    except Exception:
        parts=rest.split()
    if len(parts)==2: return parts[0], parts[1]
    if len(parts)>2:
        # find split point where second path begins with a known prefix
        for k in range(1,len(parts)):
            if re.match(r'^[a-zA-Z]/', parts[k]):
                return ' '.join(parts[:k]), ' '.join(parts[k:])
        return parts[0], parts[-1]
    if len(parts)==1: return parts[0], parts[0]
