# ---------------- Renderer methods ----------------
def _renderer_commit_regex(self):
    pat=self.cfg.get_str('commit-regex','^commit ')
    try: return re.compile(pat)
    except Exception: return re.compile(r'^commit ')
def _renderer_is_hunk_header(line):
    return re.match(r'^@@+ .*@@+ ', line+' ') or re.match(r'^@@+ -.+\+.+@@+', line) or re.match(r'^@@ -\d', line) or re.match(r'^@@@ ', line)
def _renderer_parse_hunk(line):
    m=re.match(r'^(@@+) -(\d+)(?:,(\d+))? (?:-(\d+)(?:,(\d+))? )?\+(\d+)(?:,(\d+))? \1(.*)$', line)
    if not m: return None
    # For combined, groups shift; use generic find of plus range as last +num
    plus_matches=list(re.finditer(r'\+(\d+)(?:,(\d+))?', line))
    minus_matches=list(re.finditer(r'-(\d+)(?:,(\d+))?', line))
    minus_start=int(minus_matches[0].group(1)) if minus_matches else 1
    plus_start=int(plus_matches[-1].group(1)) if plus_matches else 1
    # code after closing @@ / @@@
    # find closing sequence equal to opening
    opening=m.group(1)
    rest=line
    # locate second occurrence
    first=line.find(opening); second=line.find(opening, first+len(opening))
    code=line[second+len(opening):] if second!=-1 else ''
    if code.startswith(' '): code=code[1:]
    return {'minus_start':minus_start,'plus_start':plus_start,'code':code,'combined':len(opening)>=3}
_renderer_commit_regex= _renderer_commit_regex

def renderer_process_commit(self, raw, line):
    cfg=self.cfg
    style=cfg.styles['commit-style']
    if style.is_omit:
        self.in_commit=True; return
    # decoration
    dec_style=cfg.styles.get('commit-decoration-style')
    if style.is_raw:
        segments=[(raw, EffStyle())]
        # raw text preserved; decoration around raw would be odd, default none
        lines=paint_decorated(segments, dec_style, cfg, force_box=style.box_flag)
        for ln in lines: self.emit(ln)
    else:
        text=line
        eff=style_to_eff(style,None)
        segments=[(text,eff)]
        lines=paint_decorated(segments, dec_style, cfg, force_box=style.box_flag)
        for ln in lines: self.emit(ln)
    self.in_commit=True

def renderer_consume_file_meta_after_diff(self):
    cfg=self.cfg
    while self.i < len(self.lines):
        raw=self.lines[self.i]; line=strip_ansi(raw)
        if _renderer_is_hunk_header(line) or line.startswith('diff --git ') or line.startswith('diff --cc ') or _renderer_commit_regex(self).match(line):
            break
        fi=self.file_info
        consumed=True
        if line.startswith('--- '): fi['minus']=parse_meta_path(line)
        elif line.startswith('+++ '): fi['plus']=parse_meta_path(line)
        elif line.startswith('rename from '): fi['rename_from']=line[len('rename from '):].strip()
        elif line.startswith('rename to '): fi['rename_to']=line[len('rename to '):].strip()
        elif line.startswith('copy from '): fi['copy_from']=line[len('copy from '):].strip()
        elif line.startswith('copy to '): fi['copy_to']=line[len('copy to '):].strip()
        elif line.startswith('old mode '): fi['old_mode']=line[len('old mode '):].strip()
        elif line.startswith('new mode '): fi['new_mode']=line[len('new mode '):].strip()
        elif line.startswith('new file mode '): fi['new_file_mode']=line[len('new file mode '):].strip()
        elif line.startswith('deleted file mode '): fi['deleted_file_mode']=line[len('deleted file mode '):].strip()
        elif line.startswith('Binary files '): fi['binary']=True
        elif line.startswith('GIT binary patch'): fi['binary']=True; fi['binary_patch']=True
        else:
            # unknown file-meta lines are swallowed in FileMeta state
            consumed=True
        self.i+=1
        if fi.get('binary_patch'):
            # consume patch body until structural
            while self.i < len(self.lines):
                l2=strip_ansi(self.lines[self.i])
                if _renderer_is_hunk_header(l2) or l2.startswith('diff --') or _renderer_commit_regex(self).match(l2): break
                self.i+=1
            break
    # end while

def renderer_paint_prefix(self, record):
    cfg=self.cfg
    if not cfg.line_numbers or cfg.side_by_side: return ''
    typ=record['type']
    nm=record.get('minus_num'); np=record.get('plus_num')
    # formats
    left_text,left_spans=format_placeholder(cfg.ln_left_format, {'nm':str(nm) if nm is not None else None,'np':str(np) if np is not None else None})
    right_text,right_spans=format_placeholder(cfg.ln_right_format, {'nm':str(nm) if nm is not None else None,'np':str(np) if np is not None else None})
    def build(text, spans, placeholder_styles, literal_style_name):
        segs=[]; pos=0
        span_map={ (s,e):name for s,e,name in spans}
        # sort spans
        idx=0
        # construct segments splitting at spans
        points=[]
        for s,e,name in spans: points.append((s,e,name))
        points.sort()
        cur=0
        for s,e,name in points:
            if s>cur: segs.append((text[cur:s], style_to_eff(cfg.ln_styles[literal_style_name],None)))
            # style for number based on record type and which placeholder
            if name=='nm':
                kind='minus' if typ=='minus' else ('plus' if False else 'zero')
                if typ=='plus': kind='minus'  # nm absent but placeholder blank styled by minus? observed plus line left blank segment had minus color (88)
                # For zero both zero
                style_name='line-numbers-minus-style' if typ in ('minus','plus') else 'line-numbers-zero-style'
                if typ=='zero': style_name='line-numbers-zero-style'
            else:
                style_name='line-numbers-plus-style' if typ in ('plus','minus') else 'line-numbers-zero-style'
                if typ=='zero': style_name='line-numbers-zero-style'
            segs.append((text[s:e], style_to_eff(cfg.ln_styles[style_name],None)))
            cur=e
        if cur<len(text): segs.append((text[cur:], style_to_eff(cfg.ln_styles[literal_style_name],None)))
        return segs
    left_segs=build(left_text,left_spans,None,'line-numbers-left-style')
    right_segs=build(right_text,right_spans,None,'line-numbers-right-style')
    all_segs=left_segs+right_segs
    # prepend left style prefix as observed
    prefix=''
    left_eff=style_to_eff(cfg.ln_styles['line-numbers-left-style'],None)
    if not left_eff.is_empty(): prefix+=left_eff.prefix(cfg.true_color)
    painted,_cur=paint_segments(all_segs,cfg.true_color)
    return prefix+painted+'\x1b[0m' if painted else prefix

def renderer_get_highlighters(self):
    if self.minus_hl is None or self.plus_hl is None:
        minus_raw,plus_raw=self.file_paths()
        # language from plus if present and not /dev/null else minus
        fname=plus_raw if plus_raw not in (None,'/dev/null') else minus_raw
        if fname:
            # strip git prefix for extension detection when git
            if self.file_info and self.file_info.get('have_git'): fname_det=strip_git_prefix(fname, False)
            else: fname_det=fname
        else: fname_det=''
        self.minus_hl=Highlighter(self.cfg, fname_det)
        self.plus_hl=Highlighter(self.cfg, fname_det)
    return self.minus_hl,self.plus_hl

def renderer_paint_hunk_lines(self, records, hunk_info):
    cfg=self.cfg
    # highlight in diff order by version
    minus_hl,plus_hl=renderer_get_highlighters(self)
    for rec in records:
        if rec['type']=='zero':
            rec['syntax']=plus_hl.highlight(rec['content'])
            # advance minus hl state as well (ignore result)
            try: minus_hl.highlight(rec['content'])
            except Exception: pass
        elif rec['type']=='minus': rec['syntax']=minus_hl.highlight(rec['content'])
        elif rec['type']=='plus': rec['syntax']=plus_hl.highlight(rec['content'])
        else: rec['syntax']=[]
    # group pairing
    # partition into contiguous groups: sequences where minus/plus adjacency is handled in blocks separated by zero/no_newline
    # We will pair globally within each contiguous minus+plus segment (allowing zero in between? no)
    idx=0
    while idx < len(records):
        if records[idx]['type'] in ('minus','plus'):
            j=idx
            group=[]
            while j < len(records) and records[j]['type'] in ('minus','plus'): group.append(records[j]); j+=1
            minus_recs=[r for r in group if r['type']=='minus']; plus_recs=[r for r in group if r['type']=='plus']
            # submodule collapse: if minus and plus both subproject, drop minus records that are subproject when a plus subproject exists
            # pairing
            pairs=pair_lines([r['content'] for r in minus_recs],[r['content'] for r in plus_recs],cfg) if minus_recs and plus_recs else {}
            # map object id to emph
            for mi,(pi,me,pe) in pairs.items():
                minus_recs[mi]['emph']=me; minus_recs[mi]['has_emph']=any(me) or any(pe); minus_recs[mi]['paired']=True
                plus_recs[pi]['emph']=pe; plus_recs[pi]['has_emph']=any(me) or any(pe); plus_recs[pi]['paired']=True
            for r in group:
                if 'emph' not in r: r['emph']=[False]*len(r['content']); r['has_emph']=False; r['paired']=False
            idx=j
        else:
            records[idx]['emph']=[False]*len(records[idx]['content']); records[idx]['has_emph']=False
            idx+=1
    # drop submodule minus lines
    filtered=[]
    has_plus_sub=any(r['type']=='plus' and r['content'].startswith('Subproject commit ') for r in records)
    for r in records:
        if has_plus_sub and r['type']=='minus' and r['content'].startswith('Subproject commit '): continue
        filtered.append(r)
    records=filtered
    # paint each
    for rec in records:
        if rec['type']=='no_newline':
            self.emit(rec['raw_line']); continue
        if cfg.side_by_side and self.mode not in ('coloronly','raw'):
            continue  # side-by-side painted separately by caller grouping (handled in process_hunk)
        prefix=renderer_paint_prefix(self, rec)
        painted=renderer_paint_one_line(self, rec, prefix)
        self.emit(painted)
    return records

def renderer_paint_one_line(self, rec, prefix=''):
    cfg=self.cfg
    typ=rec['type']; content=rec['content']
    # base styles
    if typ=='minus':
        main=cfg.styles['minus-style']; non=cfg.styles['minus-non-emph-style']; emphs=cfg.styles['minus-emph-style']
    elif typ=='plus':
        main=cfg.styles['plus-style']; non=cfg.styles['plus-non-emph-style']; emphs=cfg.styles['plus-emph-style']
    else:
        main=cfg.styles['zero-style']; non=main; emphs=main
    has_emph=rec.get('has_emph',False)
    emph_arr=rec.get('emph',[False]*len(content))
    # trailing whitespace for plus
    ws_range=set()
    if typ=='plus':
        m=re.search(r'[ \t]+$', content)
        if m: ws_range=set(range(m.start(), m.end()))
    # syntax segments to char colors
    syntax_colors=[None]*len(content)
    max_syn=cfg.get_int('max-syntax-highlighting-length',400)
    pos=0
    for txt,col in rec.get('syntax',[]):
        for k,ch in enumerate(txt):
            if pos < len(syntax_colors):
                if max_syn==0 or pos < max_syn: syntax_colors[pos]=col
                else: syntax_colors[pos]=theme_color(cfg.syntax_theme,'fg') if not cfg.no_syntax else None
            pos+=1
    segments=[]
    # marker
    if self.mode=='coloronly' or (cfg.keep_plus_minus and self.mode!='diffsofancy') or self.mode=='raw':
        # In normal mode with keep_plus_minus, marker is included. In coloronly/raw, marker always part of original line (prefix char)
        marker=rec.get('marker','')
        if marker:
            # marker style: main but fg none (syntax not applied)
            meff=style_to_eff(main,None)
            # For zero marker space, style empty if zero style is syntax? zero main fg syntax would apply; marker space should be unstyled in coloronly
            if typ=='zero': meff=EffStyle(meff.bg, meff.bg, meff.attrs) if False else EffStyle(None, meff.bg, meff.attrs)
            # plus marker in coloronly observed as segment with bg only (meff fg none) good; minus same
            segments.append((marker, meff))
    elif cfg.keep_plus_minus:
        marker=rec.get('marker','')
        if marker: segments.append((marker, style_to_eff(main,None)))
    # build char segments grouped by (emph, ws, syntax_color)
    def eff_for(idx):
        if idx in ws_range:
            return style_to_eff(cfg.styles['whitespace-error-style'], syntax_colors[idx])
        st=emphs if (has_emph and idx < len(emph_arr) and emph_arr[idx]) else (non if has_emph else main)
        return style_to_eff(st, syntax_colors[idx])
    i=0
    while i < len(content):
        eff=eff_for(i); j=i+1
        while j < len(content) and eff_for(j)==eff: j+=1
        segments.append((content[i:j], eff)); i=j
    painted,cur=paint_segments(segments,cfg.true_color)
    if not cur.is_empty(): painted+='\x1b[0m'
    # fill
    # main style bg
    fill_eff=style_to_eff(main, None)
    if main.fg is not None and main.fg.kind=='syntax': fill_eff=EffStyle(None, fill_eff.bg, fill_eff.attrs)
    if fill_eff.bg is not None:
        painted+=fill_eff.prefix(cfg.true_color)+'\x1b[0K'+'\x1b[0m'
    return prefix+painted

