    fill_eff=style_to_eff(main, None)
    if main.fg is not None and main.fg.kind=='syntax': fill_eff=EffStyle(None, fill_eff.bg, fill_eff.attrs)
    if fill_eff.bg is not None:
        painted+=fill_eff.prefix(cfg.true_color)+'\x1b[0K'+'\x1b[0m'
    return prefix+painted

