# ---------------- show config / special outputs ----------------
def rust_float(v):
    try: fv=float(v)
    except Exception: return str(v)
    if fv==int(fv) and abs(fv)<1e16: return str(int(fv))
    return ('%g'%fv)
def show_config_text(cfg):
    lines=[]
