    def style_val(name):
        st=cfg.styles.get(name)
        if st is None: return ''
        disp=st.display_string(cfg.true_color)
        return paint_single(disp, style_to_eff(st,None), cfg.true_color)
    for name in ['commit-style','file-style','hunk-header-style','minus-style','minus-non-emph-style','minus-emph-style','minus-empty-line-marker-style','zero-style','plus-style','plus-non-emph-style','plus-emph-style','plus-empty-line-marker-style','grep-file-style','grep-line-number-style','whitespace-error-style']:
        add(name, style_val(name))
    # blame palette
    pal_parts=[]
    for col,rawtok in zip(cfg.blame_palette, cfg.blame_palette_raw):
        eff=EffStyle(None,col,frozenset())
        pal_parts.append(paint_single(str(rawtok), eff, cfg.true_color))
    add('blame-palette',' '.join(pal_parts))
    add('true-color','true' if cfg.true_color else 'false')
    for name,label in [('file-added-label','file-added-label'),('file-modified-label','file-modified-label'),('file-removed-label','file-removed-label'),('file-renamed-label','file-renamed-label')]:
        v=cfg.get_str(name,'')
        if name=='file-modified-label' and cfg.navigate and cfg.source(name)=='default': v=' Δ'
        add(label,f"'{v}'")
    add('right-arrow',f"'{cfg.get_str('right-arrow','')}'")
    add('hyperlinks','true' if cfg.get_bool('hyperlinks') else 'false')
    if cfg.get_bool('hyperlinks'):
        add('hyperlinks-file-link-format',f"'{cfg.get_str('hyperlinks-file-link-format','file://{path}')}'")
    add('inspect-raw-lines','true' if cfg.get_bool('inspect-raw-lines') else 'false')
    add('keep-plus-minus-markers','true' if cfg.keep_plus_minus else 'false')
    show_ln=cfg.line_numbers_user or ('side-by-side' in cfg.cli.explicit and cfg.cli.values.get('side-by-side'))
    add('line-numbers','true' if show_ln else 'false')
    if show_ln:
        for nm in ['line-numbers-minus-style','line-numbers-zero-style','line-numbers-plus-style']:
            st=cfg.ln_styles[nm]; add(nm, paint_single(st.display_string(cfg.true_color), style_to_eff(st,None), cfg.true_color))
        for nm in ['line-numbers-left-style','line-numbers-right-style']:
            st=cfg.ln_styles[nm]; add(nm, paint_single(st.display_string(cfg.true_color), style_to_eff(st,None), cfg.true_color))
        add('line-numbers-left-format',f"'{cfg.ln_left_format if not cfg.side_by_side else cfg.get_str('line-numbers-left-format','{nm:^4}⋮')}'" if False else f"'{cfg.get_str('line-numbers-left-format','') if cfg.side_by_side and cfg.source('line-numbers-left-format')!='default' else (cfg.ln_left_format if not cfg.side_by_side else '│{nm:^4}│')}'")
        # Simpler correct values: if side-by-side and not user format, cfg.ln_* already are sbs formats; if not side, they are defaults/user
        lines[-1]=f"    {'line-numbers-left-format':<30}= '{cfg.ln_left_format}'"
        add('line-numbers-right-format',f"'{cfg.ln_right_format}'")
    add('max-line-distance',rust_float(cfg.get_float('max-line-distance',0.6)))
    add('max-line-length',str(cfg.get_int('max-line-length',3000)))
    add('diff-stat-align-width',str(cfg.get_int('diff-stat-align-width',48)))
    lfm=cfg.get_str('line-fill-method',None)
    if lfm is None: lfm='ansi' if sys.stdout.isatty() else 'spaces'
    add('line-fill-method',lfm)
    add('navigate','true' if cfg.navigate else 'false')
