        add('navigate-regex',f"'{computed}'")
    else:
        add('navigate-regex',str(navr) if navr is not None else '')
    pager_raw=cfg.raw('pager')
    # pager raw is from layers; if source is default (None) show none; if user supplied show it (could be empty)
    if cfg.source('pager')=='default': add('pager','none')
