    add('syntax-theme',cfg.syntax_theme_display)
    add('width','variable' if cfg.width_mode=='variable' else str(cfg.width_val))
    add('tabs',str(cfg.get_int('tabs',8)))
    add('word-diff-regex',f"'{cfg.get_str('word-diff-regex','')}'")
    return '\n'.join(lines)+'\n'

def clone_config_for_theme(cfg, theme_name):
    # create a shallow variant for show-syntax-themes: set syntax theme and recompute styles auto? Styles largely unaffected except syntax.
    # We'll temporarily mutate and restore in caller via separate Config construction is heavy; instead return a proxy-like copy
    import copy
    new=copy.copy(cfg)
    new.syntax_theme=theme_name; new.no_syntax=(theme_name=='none'); new.syntax_theme_display=theme_name
