# ---------------- parse-ansi ----------------
def parse_ansi_text(text,cfg):
    out_lines=[]
    for raw_line in text.splitlines():
        # tokenise by ANSI sequences
        segs=[]; pos=0; cur_codes=[]
        # state
        class S: pass
        state={'fg':None,'bg':None,'attrs':set()}
        def style_name(st):
            parts=[]
            for a in ATTR_DISPLAY_ORDER:
                if a in st['attrs']: parts.append(a)
            fg=st['fg']; bg=st['bg']
            parts.append(fg.display(cfg.true_color) if fg else 'normal')
            if bg: parts.append(bg.display(cfg.true_color))
            return ' '.join(parts)
        def eff_from(st):
            return EffStyle(st['fg'], st['bg'], st['attrs'])
        i=0; buf=''
        def flush(buf, st):
            if buf=='' : return
            name=style_name(st); eff=eff_from(st)
            prefix='('+paint_single(name,eff,cfg.true_color)+')' if not eff.is_empty() else f'({name})'
            out_lines.append(prefix+paint_single(buf,eff,cfg.true_color)) if False else None
            return prefix+ (paint_single(buf,eff,cfg.true_color) if not eff.is_empty() else buf)
        pieces=[]; cur_state={'fg':None,'bg':None,'attrs':set()}; cur_text=''
        idx=0
        while idx < len(raw_line):
            m=re.match(r'\x1b\[([0-9;]*)([A-Za-z])', raw_line[idx:])
            if m and m.group(2)=='m':
                if cur_text:
                    pieces.append(flush(cur_text, cur_state)); cur_text=''
                codes=m.group(1)
                # update state
                if codes=='' : cur_state={'fg':None,'bg':None,'attrs':set()}
                else:
                    vals=[int(x) if x else 0 for x in codes.split(';')]
                    k=0
                    while k < len(vals):
                        v=vals[k]
                        if v==0: cur_state={'fg':None,'bg':None,'attrs':set()}
                        elif v==1: cur_state['attrs'].add('bold')
                        elif v==2: cur_state['attrs'].add('dim')
                        elif v==3: cur_state['attrs'].add('italic')
                        elif v==4: cur_state['attrs'].add('ul')
                        elif v==5: cur_state['attrs'].add('blink')
                        elif v==7: cur_state['attrs'].add('reverse')
                        elif v==8: cur_state['attrs'].add('hidden')
                        elif v==9: cur_state['attrs'].add('strike')
                        elif 30<=v<=37: cur_state['fg']=Color('ansi',v-30)
                        elif v==39: cur_state['fg']=None
                        elif 40<=v<=47: cur_state['bg']=Color('ansi',v-40)
                        elif v==49: cur_state['bg']=None
                        elif 90<=v<=97: cur_state['fg']=Color('ansi',v-90+8)
                        elif 100<=v<=107: cur_state['bg']=Color('ansi',v-100+8)
                        elif v==38 and k+1<len(vals):
                            if vals[k+1]==5 and k+2<len(vals): cur_state['fg']=Color('fixed',vals[k+2]); k+=2
                            elif vals[k+1]==2 and k+4<len(vals): cur_state['fg']=Color('rgb',rgb=(vals[k+2],vals[k+3],vals[k+4])); k+=4
                        elif v==48 and k+1<len(vals):
                            if vals[k+1]==5 and k+2<len(vals): cur_state['bg']=Color('fixed',vals[k+2]); k+=2
                            elif vals[k+1]==2 and k+4<len(vals): cur_state['bg']=Color('rgb',rgb=(vals[k+2],vals[k+3],vals[k+4])); k+=4
                        k+=1
                idx+=len(m.group(0)); continue
            cur_text+=raw_line[idx]; idx+=1
        if cur_text or not pieces: pieces.append(flush(cur_text if cur_text else '', cur_state) if cur_text else '(normal)')
        # If line had no text segments? original outputs (normal) for plain
        out_lines.append(''.join(pieces))
    return '\n'.join(out_lines)+('\n' if out_lines else '')

