def write_output(text,cfg,use_pager_decision=True):
    paging=cfg.get_str('paging','auto') if cfg else 'never'
    use_pager=False
    if use_pager_decision:
        if paging=='always': use_pager=True
        elif paging=='auto' and sys.stdout.isatty(): use_pager=True
    if use_pager and text:
        cmd_str=None
        if cfg and cfg.source('pager')!='default':
            cmd_str=cfg.get_str('pager','')
        if cmd_str is None:
            for ev in ('DELTA_PAGER','BAT_PAGER','PAGER'):
                if ev in os.environ: cmd_str=os.environ[ev]; break
        if cmd_str is None: cmd_str='less'
        if cmd_str and cmd_str.strip():
            try: parts=shlex.split(cmd_str)
            except Exception: parts=[]
            if parts:
                try:
                    env=dict(os.environ)
                    if os.path.basename(parts[0])=='less' and 'LESS' not in env:
                        env['LESS']='-R'
                    p=subprocess.run(parts, input=text.encode('utf-8','surrogateescape'), env=env)
                    return p.returncode if p.returncode is not None else 0
                except FileNotFoundError:
                    pass
                except BrokenPipeError:
