# ---------------- side-by-side ----------------
def renderer_prepare_records(self, records):
    cfg=self.cfg
    minus_hl,plus_hl=renderer_get_highlighters(self)
    for rec in records:
        if rec['type']=='zero':
            rec['syntax']=plus_hl.highlight(rec['content'])
            try: minus_hl.highlight(rec['content'])
            except Exception: pass
        elif rec['type']=='minus': rec['syntax']=minus_hl.highlight(rec['content'])
        elif rec['type']=='plus': rec['syntax']=plus_hl.highlight(rec['content'])
        else: rec['syntax']=[]
    idx=0
    while idx < len(records):
        if records[idx]['type'] in ('minus','plus'):
            j=idx; group=[]
            while j < len(records) and records[j]['type'] in ('minus','plus'): group.append(records[j]); j+=1
            minus_recs=[r for r in group if r['type']=='minus']; plus_recs=[r for r in group if r['type']=='plus']
            pairs=pair_lines([r['content'] for r in minus_recs],[r['content'] for r in plus_recs],cfg) if minus_recs and plus_recs else {}
            for mi,(pi,me,pe) in pairs.items():
                minus_recs[mi]['emph']=me; minus_recs[mi]['has_emph']=any(me) or any(pe); minus_recs[mi]['paired']=True; minus_recs[mi]['pair_plus']=plus_recs[pi]
                plus_recs[pi]['emph']=pe; plus_recs[pi]['has_emph']=any(me) or any(pe); plus_recs[pi]['paired']=True; plus_recs[pi]['pair_minus']=minus_recs[mi]
            for r in group:
                if 'emph' not in r: r['emph']=[False]*len(r['content']); r['has_emph']=False; r['paired']=False
            idx=j
        else:
            records[idx]['emph']=[False]*len(records[idx]['content']); records[idx]['has_emph']=False; idx+=1
    has_plus_sub=any(r['type']=='plus' and r['content'].startswith('Subproject commit ') for r in records)
    if has_plus_sub:
        records=[r for r in records if not (r['type']=='minus' and r['content'].startswith('Subproject commit '))]
    return records

def _segments_to_items(segments):
    items=[]  # (char, eff)
    for txt,eff in segments:
        for ch in txt: items.append((ch,eff))
    return items
def _items_to_segments(items):
    segs=[]
    for ch,eff in items:
        if segs and segs[-1][1]==eff: segs[-1]=(segs[-1][0]+ch,eff)
        else: segs.append((ch,eff))
    return segs
def _items_width(items): return sum(disp_width(ch) for ch,_ in items)

def renderer_wrap_items(self, items, panel_width, main_eff_bg):
    cfg=self.cfg
    if panel_width<=0: return [(items,None,False)]
    if _items_width(items)<=panel_width: return [(items,None,False)]
    wml_raw=cfg.get_str('wrap-max-lines','2')
    max_wraps=None if wml_raw=='unlimited' else cfg.get_int('wrap-max-lines',2)
    hint_eff=style_to_eff(cfg.styles.get('inline-hint-style') or parse_style('blue'), None)
    out=[]; remaining=items; wraps=0; next_right=False
    while True:
        if _items_width(remaining)<=panel_width:
            out.append((remaining,None,next_right)); break
        if max_wraps is not None and wraps>=max_wraps:
            # truncate remaining to panel-1
            chunk=[]; w=0
            for it in remaining:
                cw=disp_width(it[0])
                if w+cw>panel_width-1: break
                chunk.append(it); w+=cw
            out.append((chunk,'trunc',next_right)); break
        # take chunk fitting panel-1
        chunk=[]; w=0
        for it in remaining:
            cw=disp_width(it[0])
            if w+cw>panel_width-1: break
            chunk.append(it); w+=cw
        rest=remaining[len(chunk):]
        # decide alignment of rest
        rest_w=_items_width(rest)
