    def del_cost(a): return 2 if a[1] else 1
    def ins_cost(b): return 2 if b[1] else 1
    dp=[[0]*(n+1) for _ in range(m+1)]
    for i in range(1,m+1): dp[i][0]=dp[i-1][0]+del_cost(mt[i-1])
    for j in range(1,n+1): dp[0][j]=dp[0][j-1]+ins_cost(pt[j-1])
    for i in range(1,m+1):
        for j in range(1,n+1):
            dp[i][j]=min(dp[i-1][j-1]+sub_cost(mt[i-1],pt[j-1]), dp[i-1][j]+del_cost(mt[i-1]), dp[i][j-1]+ins_cost(pt[j-1]))
    mem=[False]*m; pep=[False]*n
    i,j=m,n
    while i>0 or j>0:
        # Determine optimal moves; prefer word-word matching/substitution, and prefer insert/delete over cross-type substitution.
        moves=[]
        if i>0 and j>0: moves.append((dp[i-1][j-1]+sub_cost(mt[i-1],pt[j-1]), 'diag'))
        if i>0: moves.append((dp[i-1][j]+del_cost(mt[i-1]), 'del'))
        if j>0: moves.append((dp[i][j-1]+ins_cost(pt[j-1]), 'ins'))
        mincost=min(v for v,_ in moves)
        opts=[name for v,name in moves if v==mincost]
        # Tie-breaking
        if i>0 and j>0 and mt[i-1][0]==pt[j-1][0] and 'ins' in opts and len(pt[j-1][0])==1 and not pt[j-1][1]:
            choice='ins'
        elif i>0 and j>0 and mt[i-1][1] and pt[j-1][1] and 'diag' in opts:
            choice='diag'
        elif i>0 and j>0 and (mt[i-1][1] != pt[j-1][1]) and ('ins' in opts or 'del' in opts):
            choice='ins' if 'ins' in opts else 'del'
        elif 'diag' in opts: choice='diag'
        elif 'ins' in opts: choice='ins'
        else: choice='del'
        if choice=='diag':
            if mt[i-1][0]!=pt[j-1][0]: mem[i-1]=True; pep[j-1]=True
            i-=1; j-=1
        elif choice=='del': mem[i-1]=True; i-=1
        else: pep[j-1]=True; j-=1
    def coalesce(toks, emph):
        emph=emph[:]
        for k in range(1,len(toks)-1):
            if not emph[k] and toks[k][0].strip()=='' and emph[k-1] and emph[k+1]: emph[k]=True
        return emph
    mem=coalesce(mt,mem); pep=coalesce(pt,pep)
    def to_ranges(toks, emph):
        arr=[]
        for (txt,isw),e in zip(toks,emph): arr.extend([e]*len(txt))
        return arr
    def word_stats(toks, emph):
        changed=0; total=0
        for (txt,isw),e in zip(toks,emph):
            if isw:
                total+=len(txt)
                if e: changed+=len(txt)
        return changed,total
    mc,mtot=word_stats(mt,mem); pc,ptot=word_stats(pt,pep)
    dist=(mc+pc)/(mtot+ptot) if (mtot+ptot) else (0.0 if minus_line==plus_line else 1.0)
    return to_ranges(mt,mem), to_ranges(pt,pep), dist, (any(mem), any(pep))
