# ---------------- raw (color-moved) lines & merge conflicts ----------------
def parse_ansi_segments(raw):
    segs=[]; state={'fg':None,'bg':None,'attrs':set()}; buf=''; i=0
    def snap(): return EffStyle(state['fg'],state['bg'],state['attrs'])
    while i < len(raw):
        m=re.match(r'\x1b\[([0-9;]*)([A-Za-z])', raw[i:])
        if m:
            if buf: segs.append((buf,snap())); buf=''
            if m.group(2)=='m':
                codes=m.group(1)
                if codes=='': state={'fg':None,'bg':None,'attrs':set()}
                else:
                    vals=[]
                    for part in codes.split(';'):
                        try: vals.append(int(part) if part else 0)
                        except Exception: vals.append(0)
                    k=0
                    while k < len(vals):
                        v=vals[k]
                        if v==0: state={'fg':None,'bg':None,'attrs':set()}
                        elif v==1: state['attrs'].add('bold')
                        elif v==2: state['attrs'].add('dim')
                        elif v==3: state['attrs'].add('italic')
                        elif v==4: state['attrs'].add('ul')
                        elif v==5: state['attrs'].add('blink')
                        elif v==7: state['attrs'].add('reverse')
                        elif v==8: state['attrs'].add('hidden')
                        elif v==9: state['attrs'].add('strike')
                        elif 30<=v<=37: state['fg']=Color('ansi',v-30)
                        elif v==39: state['fg']=None
                        elif 40<=v<=47: state['bg']=Color('ansi',v-40)
                        elif v==49: state['bg']=None
                        elif 90<=v<=97: state['fg']=Color('ansi',v-90+8)
                        elif 100<=v<=107: state['bg']=Color('ansi',v-100+8)
                        elif v==38 and k+1<len(vals):
                            if vals[k+1]==5 and k+2<len(vals): state['fg']=Color('fixed',vals[k+2]); k+=2
                            elif vals[k+1]==2 and k+4<len(vals): state['fg']=Color('rgb',rgb=(vals[k+2],vals[k+3],vals[k+4])); k+=4
                        elif v==48 and k+1<len(vals):
                            if vals[k+1]==5 and k+2<len(vals): state['bg']=Color('fixed',vals[k+2]); k+=2
                            elif vals[k+1]==2 and k+4<len(vals): state['bg']=Color('rgb',rgb=(vals[k+2],vals[k+3],vals[k+4])); k+=4
                        k+=1
