        m2=re.match(r'\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)', raw[i:])
        if m2: i+=len(m2.group(0)); continue
        buf+=raw[i]; i+=1
    if buf: segs.append((buf,snap()))
    return segs

def expected_raw_eff(cfg, typ):
    key='old' if typ=='minus' else 'new'
