            return style_to_eff(st,None)
        except Exception: pass
    return EffStyle(Color('ansi',1 if typ=='minus' else 2),None,frozenset())

def detect_and_prepare_raw(self, rec):
    cfg=self.cfg
    if rec['type'] not in ('minus','plus'): return
    if not cfg.get_bool('inspect-raw-lines'): return
